:root {
  /* =========================================================
     Surface / Elevation
     ========================================================= */
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-surface-raised: #ffffff;
  --color-surface-overlay: rgb(255 255 255 / 0.94);
  --color-surface-sunken: #f1f5f9;
  --color-surface-inverse: #0f172a;

  /* Text */
  --color-text: #0f172a;
  --color-text-secondary: #334155;
  --color-text-muted: #64748b;
  --color-text-disabled: #94a3b8;
  --color-text-link: #2563eb;
  --color-text-inverse: #f8fafc;
  --color-text-link-hover: #1d4ed8;
  --color-text-on-accent: #ffffff;

  /* Border / Divider */
  --color-border: #e2e8f0;
  --color-border-subtle: #f1f5f9;
  --color-border-strong: #cbd5e1;
  --color-divider: #e2e8f0;

  /* Accent / Brand */
  --color-accent: #2563eb;
  --color-accent-hover: #1d4ed8;
  --color-accent-active: #1e40af;
  --color-accent-subtle: #eff6ff;
  --color-accent-muted: #dbeafe;
  --color-accent-border: #93c5fd;
  --color-accent-text: #1d4ed8;
  --color-on-accent: #ffffff;
  --color-accent-secondary: #0ea5e9;
  --color-accent-secondary-subtle: #e0f2fe;

  /* Disabled / Inert */
  --color-surface-disabled: #f1f5f9;
  --color-border-disabled: #e2e8f0;
  --color-icon-disabled: #94a3b8;

  /* Form / Input */
  --color-input-bg: #ffffff;
  --color-input-border: #cbd5e1;
  --color-input-border-focus: #2563eb;
  --color-input-placeholder: #94a3b8;
  --color-input-bg-hover: #f8fafc;
  --color-input-bg-disabled: #f1f5f9;
  --color-input-border-hover: #94a3b8;
  --color-input-border-error: #dc2626;
  --color-input-text: #0f172a;
  --color-input-icon: #64748b;

  /* Brand Scale (primitive) */
  --color-brand-50: #eff6ff;
  --color-brand-100: #dbeafe;
  --color-brand-200: #bfdbfe;
  --color-brand-300: #93c5fd;
  --color-brand-400: #60a5fa;
  --color-brand-500: #3b82f6;
  --color-brand-600: #2563eb;
  --color-brand-700: #1d4ed8;
  --color-brand-800: #1e40af;
  --color-brand-900: #1e3a8a;

  /* Neutral Scale */
  --color-neutral-50: #f8fafc;
  --color-neutral-100: #f1f5f9;
  --color-neutral-200: #e2e8f0;
  --color-neutral-300: #cbd5e1;
  --color-neutral-400: #94a3b8;
  --color-neutral-500: #64748b;
  --color-neutral-600: #475569;
  --color-neutral-700: #334155;
  --color-neutral-800: #1e293b;
  --color-neutral-900: #0f172a;
  --color-neutral-950: #020617;
  --color-neutral-1000: #000b1a;

  /* Data Visualization */
  --color-chart-1: #2563eb;
  --color-chart-2: #0891b2;
  --color-chart-3: #16a34a;
  --color-chart-4: #d97706;
  --color-chart-5: #dc2626;
  --color-chart-6: #7c3aed;
  --color-chart-7: #db2777;
  --color-chart-8: #475569;
  --color-chart-grid: #e2e8f0;
  --color-chart-axis: #94a3b8;
  --color-chart-tooltip-bg: #0f172a;

  /* Interaction */
  --color-focus-ring: #60a5fa;
  --color-hover-overlay: rgb(15 23 42 / 0.04);
  --color-active-overlay: rgb(15 23 42 / 0.08);
  --color-selected: #dbeafe;
  --color-selected-subtle: #eff6ff;
  --color-pressed-overlay: rgb(15 23 42 / 0.12);

  /* Semantic State */
  --color-success: #16a34a;
  --color-success-subtle: #f0fdf4;
  --color-success-muted: #dcfce7;
  --color-success-border: #86efac;
  --color-success-text: #166534;
  --color-on-success: #ffffff;

  --color-warning: #d97706;
  --color-warning-subtle: #fffbeb;
  --color-warning-muted: #fef3c7;
  --color-warning-border: #fcd34d;
  --color-warning-text: #92400e;
  --color-on-warning: #ffffff;

  --color-danger: #dc2626;
  --color-danger-subtle: #fef2f2;
  --color-danger-muted: #fee2e2;
  --color-danger-border: #fca5a5;
  --color-danger-text: #991b1b;
  --color-on-danger: #ffffff;

  --color-info: #0284c7;
  --color-info-subtle: #f0f9ff;
  --color-info-muted: #e0f2fe;
  --color-info-border: #7dd3fc;
  --color-info-text: #075985;
  --color-on-info: #ffffff;

  /* Alpha / Overlay */
  --color-scrim: rgb(2 6 23 / 0.64);
  --color-shadow: rgb(15 23 42 / 0.12);
  --color-tint-subtle: rgb(37 99 235 / 0.04);

  /* =========================================================
     Typography
     ========================================================= */
  --font-sans: "Geist", "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-serif: "Source Serif 4", Georgia, serif;
  --font-mono: "Geist Mono", "JetBrains Mono", ui-monospace, monospace;
  --font-display: "Geist", "Inter", ui-sans-serif, system-ui, sans-serif;

  /* Display Size */
  --font-size-display-xs: clamp(2rem, 4vw, 2.75rem);
  --font-size-display-sm: clamp(2.5rem, 5vw, 3.75rem);
  --font-size-display-md: clamp(3rem, 6vw, 5rem);
  --font-size-display-lg: clamp(3.75rem, 8vw, 6.5rem);
  --font-size-display-xl: clamp(4.5rem, 10vw, 8rem);

  /* Font Size */
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;
  --font-size-7xl: 4.5rem;

  /* Font Weight */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Line Height */
  --line-height-tight: 1.1;
  --line-height-snug: 1.25;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.65;
  --line-height-none: 1;
  --line-height-loose: 1.8;

  /* Letter Spacing */
  --letter-spacing-tight: -0.04em;
  --letter-spacing-normal: 0;
  --letter-spacing-wide: 0.025em;
  --letter-spacing-wider: 0.08em;
  --letter-spacing-tighter: -0.06em;

  /* Text Measure */
  --text-measure-xs: 20ch;
  --text-measure-sm: 35ch;
  --text-measure-md: 50ch;
  --text-measure-lg: 65ch;
  --text-measure-xl: 75ch;
  --text-measure-wide: 90ch;

  /* =========================================================
     Spacing
     ========================================================= */
  --space-0: 0;
  --space-px: 1px;
  --space-0-5: 0.125rem;
  --space-1: 0.25rem;
  --space-1-5: 0.375rem;
  --space-2: 0.5rem;
  --space-2-5: 0.625rem;
  --space-3: 0.75rem;
  --space-3-5: 0.875rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-7: 1.75rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-14: 3.5rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-28: 7rem;
  --space-32: 8rem;
  --space-40: 10rem;
  --space-48: 12rem;
  --space-56: 14rem;
  --space-64: 16rem;
  --space-72: 18rem;
  --space-80: 20rem;
  --space-96: 24rem;

  /* Section Spacing */
  --section-space-xs: 2.5rem;
  --section-space-sm: 4rem;
  --section-space-md: 6rem;
  --section-space-lg: 8rem;
  --section-space-xl: 10rem;
  --section-space-2xl: 12rem;
  --section-space-3xl: 16rem;

  /* Border Radius */
  --radius-none: 0;
  --radius-xs: 0.25rem;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.25rem;
  --radius-3xl: 1.5rem;
  --radius-full: 9999px;

  /* Border Width */
  --border-width-none: 0;
  --border-width-thin: 1px;
  --border-width-medium: 2px;
  --border-width-thick: 3px;

  /* =========================================================
     Layout / Grid
     ========================================================= */
  --container-max-width-xs: 32rem;
  --container-max-width-sm: 40rem;
  --container-max-width-md: 48rem;
  --container-max-width-lg: 64rem;
  --container-max-width-xl: 80rem;
  --container-max-width-2xl: 90rem;

  --container-padding-sm: 1rem;
  --container-padding-md: 1.5rem;
  --container-padding-lg: 2rem;
  --container-padding-xl: 3rem;
  --container-padding-2xl: 4rem;

  --grid-columns: 4;
  --grid-columns-sm: 4;
  --grid-columns-md: 8;
  --grid-columns-lg: 12;
  --grid-columns-xl: 12;

  --grid-gutter: 1rem;
  --grid-gutter-sm: 1.25rem;
  --grid-gutter-md: 1.5rem;
  --grid-gutter-lg: 2rem;
  --grid-gutter-xl: 2.5rem;

  --grid-margin-sm: 1rem;
  --grid-margin-md: 1.5rem;
  --grid-margin-lg: 2rem;
  --grid-margin-xl: 3rem;

  /* Composition */
  --composition-max-width: 75rem;
  --composition-max-width-wide: 90rem;
  --composition-max-width-narrow: 48rem;
  --composition-gutter: clamp(1rem, 4vw, 4rem);
  --composition-offset-sm: 2rem;
  --composition-offset-md: 4rem;
  --composition-offset-lg: 8rem;
  --composition-overlap-sm: -1rem;
  --composition-overlap-md: -2rem;
  --composition-overlap-lg: -4rem;
  --composition-aspect-wide: 16 / 9;
  --composition-aspect-standard: 4 / 3;
  --composition-aspect-square: 1 / 1;
  --composition-aspect-portrait: 3 / 4;

  /* Media */
  --media-radius: var(--radius-xl);
  --media-radius-sm: var(--radius-md);
  --media-radius-lg: var(--radius-2xl);
  --media-radius-xl: var(--radius-3xl);
  --media-aspect-wide: 21 / 9;
  --media-aspect-video: 16 / 9;
  --media-aspect-standard: 4 / 3;
  --media-aspect-square: 1 / 1;
  --media-aspect-portrait: 3 / 4;
  --media-overlay: linear-gradient(
    180deg,
    rgb(2 6 23 / 0) 25%,
    rgb(2 6 23 / 0.72) 100%
  );
  --media-overlay-subtle: linear-gradient(
    180deg,
    rgb(2 6 23 / 0) 45%,
    rgb(2 6 23 / 0.38) 100%
  );
  --media-overlay-strong: linear-gradient(
    180deg,
    rgb(2 6 23 / 0.08) 0%,
    rgb(2 6 23 / 0.86) 100%
  );

  /* =========================================================
     Sizes
     ========================================================= */
  --size-icon-xs: 0.875rem;
  --size-icon-sm: 1rem;
  --size-icon-md: 1.25rem;
  --size-icon-lg: 1.5rem;
  --size-icon-xl: 2rem;

  --size-control-xs: 1.75rem;
  --size-control-sm: 2rem;
  --size-control-md: 2.5rem;
  --size-control-lg: 3rem;
  --size-control-xl: 3.5rem;

  --size-avatar-xs: 1.5rem;
  --size-avatar-sm: 2rem;
  --size-avatar-md: 2.5rem;
  --size-avatar-lg: 3rem;
  --size-avatar-xl: 4rem;

  --size-header-height: 4.5rem;
  --size-header-height-mobile: 4rem;
  --size-sidebar-width: 17rem;
  --size-sidebar-width-collapsed: 4.5rem;

  /* Control Geometry */
  --control-padding-x-xs: 0.625rem;
  --control-padding-x-sm: 0.75rem;
  --control-padding-x-md: 1rem;
  --control-padding-x-lg: 1.25rem;
  --control-padding-x-xl: 1.5rem;

  --control-padding-y-xs: 0.25rem;
  --control-padding-y-sm: 0.375rem;
  --control-padding-y-md: 0.625rem;
  --control-padding-y-lg: 0.75rem;
  --control-padding-y-xl: 0.875rem;

  --control-radius: var(--radius-md);
  --control-border-width: 1px;
  --control-icon-gap: 0.5rem;

  /* Iconography */
  --icon-stroke-width-thin: 1.25px;
  --icon-stroke-width: 1.5px;
  --icon-stroke-width-medium: 2px;
  --icon-stroke-width-bold: 2.5px;
  --icon-gap-xs: 0.25rem;
  --icon-gap-sm: 0.375rem;
  --icon-gap-md: 0.5rem;

  /* =========================================================
     Shadow / Elevation
     ========================================================= */
  --shadow-xs: 0 1px 2px rgb(15 23 42 / 0.04);
  --shadow-sm: 0 2px 6px rgb(15 23 42 / 0.06);
  --shadow-md: 0 6px 16px rgb(15 23 42 / 0.08);
  --shadow-lg: 0 12px 32px rgb(15 23 42 / 0.1);
  --shadow-xl: 0 20px 48px rgb(15 23 42 / 0.12);
  --shadow-2xl: 0 32px 72px rgb(15 23 42 / 0.16);
  --shadow-inner: inset 0 1px 3px rgb(15 23 42 / 0.08);
  --shadow-focus: 0 0 0 3px rgb(96 165 250 / 0.32);
  --shadow-outline: 0 0 0 1px rgb(37 99 235 / 0.4);

  /* Glow / Light Effects */
  --glow-sm: 0 0 16px rgb(37 99 235 / 0.14);
  --glow-md: 0 0 28px rgb(37 99 235 / 0.18);
  --glow-lg: 0 0 48px rgb(37 99 235 / 0.22);
  --glow-xl: 0 0 80px rgb(37 99 235 / 0.26);

  /* Blur */
  --blur-sm: 4px;
  --blur-md: 8px;
  --blur-lg: 16px;
  --blur-xl: 24px;

  /* Gradient */
  --gradient-brand: linear-gradient(135deg, #2563eb 0%, #0ea5e9 100%);
  --gradient-brand-subtle: linear-gradient(
    135deg,
    #eff6ff 0%,
    #e0f2fe 100%
  );
  --gradient-surface: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  --gradient-surface-subtle: linear-gradient(
    180deg,
    #f8fafc 0%,
    #f1f5f9 100%
  );
  --gradient-glow: radial-gradient(
    circle at center,
    rgb(37 99 235 / 0.2),
    transparent 68%
  );
  --gradient-fade: linear-gradient(
    90deg,
    transparent 0%,
    rgb(15 23 42 / 0.08) 50%,
    transparent 100%
  );
  --gradient-hero: radial-gradient(
      circle at 80% 20%,
      rgb(37 99 235 / 0.14),
      transparent 34%
    ),
    linear-gradient(135deg, #f8fafc 0%, #eff6ff 100%);

  /* =========================================================
     Opacity / Motion
     ========================================================= */
  --opacity-hover: 0.88;
  --opacity-disabled: 0.48;
  --opacity-active: 0.76;
  --opacity-selected: 0.16;
  --opacity-muted: 0.64;
  --opacity-overlay: 0.72;

  --duration-instant: 0ms;
  --duration-fast: 120ms;
  --duration-normal: 200ms;
  --duration-slow: 320ms;
  --duration-slower: 480ms;
  --duration-slowest: 720ms;

  --motion-distance-xs: 2px;
  --motion-distance-sm: 4px;
  --motion-distance-md: 8px;
  --motion-distance-lg: 16px;
  --motion-distance-xl: 32px;

  --motion-scale-hover: 1.015;
  --motion-scale-active: 0.985;
  --motion-scale-enter: 0.98;
  --motion-scale-exit: 0.985;

  --motion-blur-enter: 8px;
  --motion-blur-exit: 4px;

  /* Easing */
  --ease-linear: linear;
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-smooth: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-emphasized: cubic-bezier(0.2, 0, 0, 1);

  /* Semantic Motion */
  --motion-enter: opacity var(--duration-slow) var(--ease-spring),
    transform var(--duration-slow) var(--ease-spring);
  --motion-exit: opacity var(--duration-normal) var(--ease-in),
    transform var(--duration-normal) var(--ease-in);
  --motion-hover: transform var(--duration-fast) var(--ease-out),
    box-shadow var(--duration-fast) var(--ease-out),
    background-color var(--duration-fast) var(--ease-out);
  --motion-press: transform var(--duration-fast) var(--ease-out);
  --motion-reveal: opacity var(--duration-slower) var(--ease-spring),
    transform var(--duration-slower) var(--ease-spring);
  --motion-layout: all var(--duration-normal) var(--ease-smooth);
  --motion-modal: opacity var(--duration-normal) var(--ease-out),
    transform var(--duration-slow) var(--ease-spring);
  --motion-page: opacity var(--duration-slow) var(--ease-smooth),
    transform var(--duration-slow) var(--ease-smooth);

  /* =========================================================
     Z-Index
     ========================================================= */
  --z-base: 0;
  --z-raised: 1;
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-overlay: 300;
  --z-modal: 400;
  --z-popover: 500;
  --z-toast: 600;
  --z-tooltip: 700;

  /* Breakpoint */
  --breakpoint-xs: 30rem;
  --breakpoint-sm: 40rem;
  --breakpoint-md: 48rem;
  --breakpoint-lg: 64rem;
  --breakpoint-xl: 80rem;
  --breakpoint-2xl: 96rem;

  /* Accessibility */
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
  --focus-ring-radius: var(--radius-md);
  --touch-target-min: 2.75rem;

  /* =========================================================
     Component / Button
     ========================================================= */
  --button-height-sm: 2rem;
  --button-height-md: 2.5rem;
  --button-height-lg: 3rem;
  --button-height-xl: 3.5rem;

  --button-padding-x-sm: 0.75rem;
  --button-padding-x-md: 1rem;
  --button-padding-x-lg: 1.25rem;
  --button-padding-x-xl: 1.5rem;

  --button-radius: var(--radius-md);
  --button-icon-size: 1.125rem;
  --button-gap: 0.5rem;

  /* Component / Card */
  --card-padding-sm: 1rem;
  --card-padding-md: 1.5rem;
  --card-padding-lg: 2rem;
  --card-padding-xl: 2.5rem;
  --card-radius: var(--radius-xl);
  --card-border-width: 1px;
  --card-shadow: var(--shadow-sm);

  /* Component / Navigation */
  --nav-height: 4.5rem;
  --nav-padding-x: 1.5rem;
  --nav-gap: 1.5rem;
  --nav-item-height: 2.5rem;
  --nav-item-radius: var(--radius-md);

  /* Component / Badge */
  --badge-height-sm: 1.5rem;
  --badge-height-md: 1.75rem;
  --badge-padding-x: 0.625rem;
  --badge-radius: var(--radius-full);
  --badge-gap: 0.375rem;

  /* Component / Modal */
  --modal-width-sm: 24rem;
  --modal-width-md: 32rem;
  --modal-width-lg: 48rem;
  --modal-width-xl: 64rem;
  --modal-padding: 1.5rem;
  --modal-radius: var(--radius-2xl);
  --modal-shadow: var(--shadow-2xl);

  /* Component / Tooltip */
  --tooltip-max-width: 20rem;
  --tooltip-padding-x: 0.75rem;
  --tooltip-padding-y: 0.5rem;
  --tooltip-radius: var(--radius-sm);

  /* Component / Input */
  --input-height-sm: 2rem;
  --input-height-md: 2.5rem;
  --input-height-lg: 3rem;
  --input-padding-x: 0.75rem;
  --input-padding-y: 0.625rem;
  --input-radius: var(--radius-md);
  --input-border-width: 1px;

  /* Component / Avatar */
  --avatar-ring-width: 2px;
  --avatar-ring-color: #ffffff;
  --avatar-group-overlap: -0.5rem;

  /* Component / Divider */
  --divider-width: 1px;
  --divider-spacing: 1.5rem;

  /* Component / Overlay */
  --overlay-opacity: 0.72;
  --overlay-blur: 8px;
  --overlay-radius: var(--radius-xl);

  /* Responsive Layout */
  --mobile-page-padding: 1rem;
  --mobile-section-spacing: 4rem;
  --mobile-content-gap: 1.25rem;
  --mobile-grid-gap: 1rem;

  --desktop-page-padding: 2rem;
  --desktop-section-spacing: 8rem;
  --desktop-content-gap: 2rem;
  --desktop-grid-gap: 1.5rem;
}
